     3	use serde::Serialize;
     4	use std::path::Path;
     5	
     6	#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
     7	pub struct FunctionRecord {
     8	    pub file: String,
     9	    pub name: Option<String>,
    10	    pub start_line: usize,
    11	    pub end_line: usize,
    12	    pub kind: String,
    13	}
    14	
    15	pub fn functions_inventory(repo: &Path) -> anyhow::Result<Vec<FunctionRecord>> {
    16	    let loaded = crate::repo_loader::load_repo(repo)?;
    17	    let mut out = Vec::new();
    18	    for (file, pf) in &loaded.files {
    19	        let lang = pf.language.tree_sitter_language();
    20	        let recs: Vec<FunctionRecord> = pf
    21	            .functions()
    22	            .iter()
    23	            .map(|f| FunctionRecord {
    24	                file: file.clone(),
    25	                name: f.name.clone(),
    26	                start_line: f.start_line,
    27	                end_line: f.end_line,
    28	                kind: lang
    29	                    .node_kind_for_id(f.kind_id)
    30	                    .unwrap_or("unknown")
    31	                    .to_string(),
    32	            })
    33	            .collect();
    34	        // §2.3 dedup: tree-sitter-python captures BOTH (decorated_definition)
    35	        // wrappers and the inner function_definition. Wrapper kinds never survive
    36	        // over their inner definition.
    37	        let mut keep = vec![true; recs.len()];
    38	        for i in 0..recs.len() {
    39	            for j in 0..recs.len() {
    40	                if i == j {
    41	                    continue;
    42	                }
    43	                let (outer, inner) = (&recs[i], &recs[j]);
    44	                let contains = outer.start_line <= inner.start_line
    45	                    && inner.end_line <= outer.end_line
    46	                    && (outer.start_line, outer.end_line) != (inner.start_line, inner.end_line);
    47	                let wrapper = outer.kind == "decorated_definition";
    48	                if contains && wrapper {
    49	                    keep[i] = false;
    50	                }
    51	            }
    52	        }
    53	        let mut it = keep.iter();
    54	        let mut recs = recs;
    55	        recs.retain(|_| *it.next().unwrap());
    56	        out.extend(recs);
    57	    }
    58	    out.sort_by(|a, b| {
    59	        (&a.file, a.start_line, a.end_line).cmp(&(&b.file, b.start_line, b.end_line))
    60	    });
    61	    out.dedup();
    62	    Ok(out)
    63	}

