    13	/// Shape of a multi-target-Exact call site — what *kind* of receiver/qualifier
    14	/// minted the colliding pool. This decides which lever could address it:
    15	/// `type_path` (`T::m`) is the only shape the proposed Option-B owner-key
    16	/// narrowing targets; `receiver_typed` (`x.m()` recovered) is a different path
    17	/// (the receiver `methods_by_scope` hook); `qualifier_field` is the ambiguous
    18	/// `pkg.f()`/`x.m()` form (`CallSite.qualifier` cannot tell type from value).
    19	fn multi_target_shape(site: &CallSite) -> &'static str {
    20	    if site.callee_name.contains("::") {
    21	        let mut segs: Vec<&str> = site.callee_name.split("::").collect();
    22	        if segs.pop().is_none() {
    23	            return "unshaped";
    24	        }
    25	        while matches!(segs.first(), Some(&"crate") | Some(&"super")) {
    26	            segs.remove(0);
    27	        }
    28	        if segs.as_slice() == ["self"] || segs.last() == Some(&"Self") {
    29	            return "self_path";
    30	        }
    31	        if segs.is_empty() {
    32	            return "unshaped";
    33	        }
    34	        return "type_path";
    35	    }
    36	    if site.receiver_outcome.is_some() {
    37	        return "receiver_typed";
    38	    }
    39	    if site.qualifier.is_some() {
    40	        return "qualifier_field";
    41	    }
    42	    "unshaped"
    43	}
