    45	/// Shadow (measurement-only) of the Option-B narrowing for a genuine `T::m`
    46	/// type-path site: resolve the owner type-path through the scope graph and report
    47	/// whether `methods_by_scope` would narrow the colliding pool to a singleton (the
    48	/// realized precision win), to a still-multiple set (would demote to NameOnly), or
    49	/// cannot (fail-open, split by cause). Only called for `type_path` sites — never
    50	/// changes resolution behavior.
    51	fn shadow_narrow_type_path(cg: &CallGraph, site: &CallSite) -> &'static str {
    52	    let mut segs: Vec<&str> = site.callee_name.split("::").collect();
    53	    let Some(method) = segs.pop() else {
    54	        return "failopen_type_unresolved";
    55	    };
    56	    while matches!(segs.first(), Some(&"crate") | Some(&"super")) {
    57	        segs.remove(0);
    58	    }
    59	    let owner_syntax = segs.join("::");
    60	    let Some(graph) = cg.scope_graph.as_ref() else {
    61	        return "failopen_no_graph";
    62	    };
    63	    let resolved = graph
    64	        .file_paths
    65	        .get(&site.caller.file)
    66	        .copied()
    67	        .and_then(|file| CallGraph::module_scope_for_byte(graph, file, site.start_byte))
    68	        .and_then(|from| resolve_type_path_to_type_scope(graph, from, &owner_syntax));
    69	    match resolved {
    70	        Some(TypeKey::InRepo(scope)) => {
    71	            match cg
    72	                .methods_by_scope
    73	                .get(&(scope, method.to_string()))
    74	                .map(|c| c.len())
    75	            {
    76	                Some(1) => "singleton",
    77	                Some(n) if n > 1 => "multiple",
    78	                _ => "failopen_no_method",
    79	            }
    80	        }
    81	        _ => "failopen_type_unresolved",
    82	    }
    83	}
