   601	fn fid_of(sym: &SymbolRef) -> FunctionId {
   602	    match sym {
   603	        // `..` — SymbolRef::Function also has `ordinal` (R2-B1).
   604	        SymbolRef::Function {
   605	            name,
   606	            file,
   607	            start_line,
   608	            end_line,
   609	            ..
   610	        } => FunctionId {
   611	            name: name.clone(),
   612	            file: file.clone(),
   613	            start_line: *start_line,
   624	    target: &FunctionId,
   625	) -> Vec<(FunctionId, crate::navigation::call_resolve::NavCallEdge<'a>)> {
   626	    let mut out = Vec::new();
   627	    let cg = &s.index.cpg.call_graph;
   628	    for site in crate::navigation::call_resolve::scoped_caller_sites(cg, &target.name) {
   629	        let resolved = crate::navigation::call_resolve::resolve_site_nav(cg, site);
   630	        for edge in resolved {
   631	            if *edge.target == *target {
   632	                out.push((site.caller.clone(), edge));
   633	            }
   634	        }
   635	    }
   636	    out
   637	}
